import sys; sys.path.insert(0, __import__("pathlib").Path(__file__).resolve().parents[1].as_posix())
from explications import *

ENTREES = [
    ("## 🗝️ Vocabulaire", 'fin', apropos("Pourquoi ne peut-on pas simplement « coller » les pattes d'un composant sur la carte avec de l'étain froid ?", "Parce que l'étain doit **fondre** et **mouiller** à la fois la **patte** et la **pastille** de cuivre : c'est un vrai **alliage** qui assure la liaison **électrique** et **mécanique**. Si l'étain ne fond pas bien, on obtient une **brasure froide**, qui conduit mal et finit par casser.\n\nDans cette séance, tu apprends le **geste**, la **norme de qualité** et le **contrôle** d'une soudure.")),
    ("## 1.", 'fin', clair("Le fer à souder **ne soude pas** : il **transfère de la chaleur**. C'est la **chaleur** du fer qui fait fondre l'étain, jamais le contact direct de l'étain avec la panne.\n\n- **Température** : environ **360 °C** pour l'étain sans plomb (SAC305).\n- **Étain** : il contient du **flux**, qui nettoie le cuivre pour que l'étain « accroche ».\n- **Tresse** ou **pompe** : pour retirer un excès d'étain.") + "\n" + verifie(
        ("À quoi sert le flux ?", "Il **nettoie** les surfaces de cuivre (il enlève les oxydes) pour que l'étain **mouille** bien."),
        ("À quelle température règle-t-on le fer pour de l'étain sans plomb ?", "Entre **360 et 380 °C** environ."),
        ("Combien de temps le fer doit-il rester en contact avec une brasure ?", "**2 à 3 secondes au maximum**, sinon la pastille risque de se décoller.")) + "\n" + retenir("Le fer chauffe la patte et la pastille ; c'est cette chaleur qui fait fondre l'étain.", "Contact : 2 à 3 secondes maximum.")),
    ("## 2.", 'fin', clair("Une bonne soudure se fait **toujours dans le même ordre** :\n\n1. **Insérer** le composant (attention au sens).\n2. **Chauffer** la patte **et** la pastille ensemble.\n3. **Apporter l'étain** sur la zone chauffée, **du côté opposé à la panne**.\n4. **Retirer l'étain**, **puis le fer**.\n5. **Laisser refroidir** sans bouger ni souffler, puis **couper** la patte.") + "\n" + erreurs("Poser l'étain sur la panne du fer : il fond mais ne mouille pas la pastille.", "Souffler sur la soudure pour la refroidir : elle cristallise trop vite (brasure froide).", "Bouger la carte pendant le refroidissement : brasure « collée », fragile.") + "\n" + verifie(
        ("Quel est l'ordre des deux retraits à l'étape 4 ?", "On retire **d'abord l'étain**, **puis le fer**."),
        ("Où amène-t-on l'étain ?", "Sur la **zone chauffée**, du côté **opposé à la panne** : c'est la chaleur de la patte et de la pastille qui le fait fondre."),
        ("Pourquoi ne faut-il pas souffler sur la soudure ?", "Un refroidissement trop rapide donne une **brasure froide** (mate et granuleuse).")) + "\n" + retenir("Chauffer, étain, retirer l'étain, retirer le fer, refroidir.")),
    ("## 3.", 'fin', clair("La norme **IPC-A-610** dit **ce qu'on accepte ou refuse** pour une soudure. Il y a **trois classes** : **Classe 1** (grand public), **Classe 2** (industrie, ce qu'on vise) et **Classe 3** (santé, aéronautique, haute fiabilité).\n\nUne **bonne brasure** est **brillante, lisse, en forme de cône légèrement creusé**, elle **recouvre** bien la pastille et la patte.\n\nUne **mauvaise brasure** se repère à son **aspect** : mate et granuleuse (froide), boule d'étain (excès), étain entre deux pastilles (pont), pastille décollée (délaminage).") + "\n" + verifie(
        ("Quelle classe IPC vise-t-on en formation ?", "La **Classe 2** (électronique industrielle et professionnelle)."),
        ("Une soudure est mate et granuleuse. Comment s'appelle ce défaut ? Quelle est sa cause ?", "Une **brasure froide** : le fer n'était pas assez chaud ou le contact a été trop court."),
        ("Quel défaut est irréparable ?", "Le **délaminage** (pastille décollée par surchauffe) : la carte est abîmée.")) + "\n" + retenir("Brasure correcte : brillante, lisse, en cône creusé.", "Défauts : froide, pont, excès, manque, collée, soufflure, délaminage.")),
    ("## 4.", 'fin', clair("On soude **du plus plat au plus grand** : ainsi la carte posée à l'envers **reste stable** et les composants hauts ne gênent pas l'accès aux plus petits.\n\n**Ordre :** straps, résistances, diodes, condensateurs céramiques, connecteurs, condensateurs électrolytiques, puis LED et transistors.") + "\n" + verifie(
        ("Pourquoi soude-t-on les composants hauts en dernier ?", "Pour que la carte reste **stable à l'envers** et pour **garder l'accès** aux petits composants."),
        ("Quels composants demandent de respecter la **polarité** ?", "Les **diodes**, les **LED**, les **condensateurs électrolytiques** et les **transistors**.")) ),
    ("## 5.", 'fin', clair("Après la soudure, **contrôle avant d'alimenter** :\n\n1. **Regarde** chaque brasure à la loupe (aspect, pont, remplissage).\n2. **Vérifie** les polarités.\n3. **Teste** la continuité de l'alimentation et l'absence de court-circuit entre + et − (en mode ohmmètre, hors tension).\n4. **Alimente** seulement si tout est bon.") + "\n" + verifie(
        ("Quel test réalise-t-on avant d'alimenter la carte ?", "La **continuité de l'alimentation** et l'**absence de court-circuit** entre + et −, **hors tension**."),
        ("Quelle valeur mesure-t-on entre + et − si tout va bien ?", "Une résistance **supérieure à 1 kΩ** (pas un court-circuit).")) + "\n" + retenir("Regarder, vérifier les sens, tester hors tension, puis alimenter.")),
]
